<?php $e = static fn($value): string => htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8'); ?>
<style>.finance-stats{grid-template-columns:repeat(3,1fr)}.finance-stat{padding:22px 24px}.finance-stat p{margin:8px 0 4px;color:var(--muted)}.finance-stat strong{font:700 25px 'Space Grotesk'}.finance-section{margin-top:20px}.finance-section .panel-head{align-items:flex-start}.withdrawal-note{color:var(--muted);font-size:13px}.finance-table .incoming{color:#16804f;font-weight:700}.finance-table .outgoing{color:#bd4b4b;font-weight:700}.refund-form{display:grid;grid-template-columns:1fr 1fr 1fr 180px;gap:18px;padding:24px}.refund-form label{display:flex;flex-direction:column;gap:8px;margin:0;color:var(--ink);font-size:13px;font-weight:700}.refund-form .field{width:100%;height:44px;margin:0;padding:10px 12px}.refund-form .btn{align-self:end;height:44px;white-space:nowrap}@media(max-width:760px){.finance-stats{grid-template-columns:1fr}.refund-form{grid-template-columns:1fr;padding:20px}.refund-form .btn{width:100%}}
