<div class="stats finance-stats"><div class="stat finance-stat"><i class="fa-solid fa-chart-column"></i><p>Total omset selesai</p><strong><?= formatRupiah($financeStats['omzet']) ?></strong></div><div class="stat finance-stat"><i class="fa-solid fa-building-columns"></i><p>Keuntungan bersih admin (<?= PLATFORM_FEE_PERCENT ?>%)</p><strong><?= formatRupiah($financeStats['admin']) ?></strong></div><div class="stat finance-stat"><i class="fa-solid fa-wallet"></i><p>Total dibayarkan ke joki</p><strong><?= formatRupiah($financeStats['joki']) ?></strong></div></div>
<div class="panel finance-section"><div class="panel-head"><div><h2>Permintaan penarikan</h2><p class="withdrawal-note">Konfirmasi setelah transfer manual ke rekening atau e-wallet joki.</p></div></div><div class="table-wrap"><table><thead><tr><th>Joki</th><th>WhatsApp</th><th>Saldo tersedia</th><th>Nominal tarik</th><th>Bukti transfer</th><th>Aksi</th></tr></thead><tbody><?php foreach ($withdrawalRequests as $request): ?><?php $payoutFormId = 'payout-' . (int) $request['id']; ?><tr><td><form id="<?= $e($payoutFormId) ?>" method="post" enctype="multipart/form-data"><input type="hidden" name="action" value="confirm_withdrawal"><input type="hidden" name="csrf" value="<?= $e(adminCsrf()) ?>"><input type="hidden" name="joki_id" value="<?= (int) $request['id'] ?>"></form><strong><?= $e($request['nama']) ?></strong></td><td><?= $e($request['whatsapp']) ?></td><td><?= formatRupiah($request['saldo_joki']) ?></td><td><strong><?= formatRupiah($request['withdrawal_amount']) ?></strong></td><td><input form="<?= $e($payoutFormId) ?>" type="file" name="bukti_transfer" accept="image/jpeg,image/png,image/webp,application/pdf" required></td><td><button form="<?= $e($payoutFormId) ?>" class="btn small"><i class="fa-solid fa-check"></i> Konfirmasi Pembayaran</button></td></tr><?php endforeach; ?><?php if (!$withdrawalRequests): ?><tr><td colspan="6" class="empty">Belum ada permintaan penarikan dana.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="panel finance-section"><div class="panel-head"><h2>Histori transaksi bagi hasil</h2></div><div class="table-wrap"><table class="finance-table"><thead><tr><th>Tanggal</th><th>Order</th><th>Joki</th><th>Tipe</th><th>Total</th><th>Bagian admin</th><th>Bagian joki</th></tr></thead><tbody><?php foreach ($financeTransactions as $transaction): ?><tr><td><?= date('d M Y, H:i', strtotime($transaction['tanggal'])) ?></td><td><?= $e($transaction['order_code'] ?: '-') ?></td><td><?= $e($transaction['joki_name'] ?: '-') ?></td><td class="<?= $transaction['tipe'] === 'masuk' ? 'incoming' : 'outgoing' ?>"><?= $transaction['tipe'] === 'masuk' ? 'Fee split' : 'Penarikan' ?></td><td><?= formatRupiah($transaction['total_bayar']) ?></td><td><?= formatRupiah($transaction['bagian_admin']) ?></td><td><?= formatRupiah($transaction['bagian_joki']) ?></td></tr><?php endforeach; ?><?php if (!$financeTransactions): ?><tr><td colspan="7" class="empty">Belum ada histori transaksi.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="panel finance-section"><div class="panel-head"><div><h2>Catat refund / garansi</h2><p class="withdrawal-note">Masukkan pengembalian dana untuk menjaga keuntungan admin tetap akurat.</p></div></div><form class="refund-form" method="post"><input type="hidden" name="action" value="create_refund"><input type="hidden" name="csrf" value="<?= $e(adminCsrf()) ?>"><label>Order ID<input class="field" type="number" name="order_id" min="1" placeholder="Contoh: 123" required></label><label>Nominal refund<input class="field" type="number" name="nominal_refund" min="1" placeholder="Rp" required></label><label>Alasan<select class="field" name="alasan" required><option value="">Pilih alasan</option><option value="revisi_gagal">Revisi gagal</option><option value="cancel">Cancel</option><option value="garansi">Garansi</option></select></label><button class="btn"><i class="fa-solid fa-plus"></i> Simpan refund</button></form></div>
<div class="panel finance-section"><div class="panel-head"><h2>Log refund</h2></div><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Order</th><th>Alasan</th><th>Nominal</th><th>Status</th></tr></thead><tbody><?php foreach ($refundLogs as $refund): ?><tr><td><?= date('d M Y, H:i', strtotime($refund['tanggal_refund'])) ?></td><td><?= $e($refund['order_code'] ?: $refund['id_pesanan']) ?></td><td><?= $e(ucwords(str_replace('_', ' ', $refund['alasan']))) ?></td><td><?= formatRupiah($refund['nominal_refund']) ?></td><td><?= $e(ucfirst($refund['status'])) ?></td></tr><?php endforeach; ?><?php if (!$refundLogs): ?><tr><td colspan="5" class="empty">Belum ada refund tercatat.</td></tr><?php endif; ?></tbody></table></div></div>
